import React, { useState } from "react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { AlertCircle, Upload } from "lucide-react";
import ChatMessage from "./components/ChatMessage";
import Timer from "./components/Timer";
import ScoreChart from "./components/ScoreChart";

// Main App Component
function App() {
  const [activeTab, setActiveTab] = useState("interviewee");
  const [messages, setMessages] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [selectedCandidate, setSelectedCandidate] = useState(null);

  const handleSendMessage = (message) => {
    setMessages([...messages, { text: message, sender: "user" }]);
    setTimeout(() => {
      setMessages((prev) => [
        ...prev,
        { text: "This is an AI response", sender: "ai" },
      ]);
    }, 1000);
  };

  const handleResumeUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      setCandidates([
        ...candidates,
        {
          id: Date.now(),
          name: file.name,
          resume: URL.createObjectURL(file),
          score: Math.floor(Math.random() * 100),
        },
      ]);
    }
  };

  return (
    <div className="container mx-auto p-4">
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid w-full grid-cols-2">
          <TabsTrigger value="interviewee">Interviewee</TabsTrigger>
          <TabsTrigger value="interviewer">Interviewer</TabsTrigger>
        </TabsList>

        {/* Interviewee Section */}
        <TabsContent value="interviewee">
          <Card>
            <CardContent className="p-4 space-y-4">
              <div className="flex items-center space-x-2">
                <Input type="file" onChange={handleResumeUpload} />
                <Button>
                  <Upload className="w-4 h-4 mr-2" /> Upload Resume
                </Button>
              </div>
              <div className="h-96 border rounded p-2 overflow-y-auto">
                {messages.map((msg, index) => (
                  <ChatMessage key={index} message={msg} />
                ))}
              </div>
              <div className="flex space-x-2">
                <Input
                  placeholder="Type your message..."
                  onKeyDown={(e) => {
                    if (e.key === "Enter") handleSendMessage(e.target.value);
                  }}
                />
                <Button
                  onClick={() =>
                    handleSendMessage("Sample message")
                  }
                >
                  Send
                </Button>
              </div>
              <Timer />
            </CardContent>
          </Card>
        </TabsContent>

        {/* Interviewer Section */}
        <TabsContent value="interviewer">
          <div className="grid grid-cols-3 gap-4">
            <Card className="col-span-1">
              <CardContent className="p-4 space-y-2">
                {candidates.map((candidate) => (
                  <div
                    key={candidate.id}
                    className={`p-2 border rounded cursor-pointer ${
                      selectedCandidate?.id === candidate.id
                        ? "bg-gray-200"
                        : ""
                    }`}
                    onClick={() => setSelectedCandidate(candidate)}
                  >
                    {candidate.name}
                  </div>
                ))}
              </CardContent>
            </Card>

            <Card className="col-span-2">
              <CardContent className="p-4 space-y-4">
                {selectedCandidate ? (
                  <>
                    <h2 className="text-xl font-bold">
                      {selectedCandidate.name}
                    </h2>
                    <p>Score: {selectedCandidate.score}</p>
                    <ScoreChart score={selectedCandidate.score} />
                  </>
                ) : (
                  <div className="flex items-center space-x-2 text-gray-500">
                    <AlertCircle className="w-5 h-5" />
                    <span>Select a candidate to view details</span>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
}

export default App;
